#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
in highp vec4 in_POSITION0;
in mediump vec4 in_COLOR0;
in highp vec2 in_TEXCOORD0;
out mediump vec4 vs_COLOR0;
out highp vec2 vs_TEXCOORD0;
vec4 u_xlat0;
vec4 u_xlat1;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    vs_COLOR0 = in_COLOR0;
    vs_TEXCOORD0.xy = in_TEXCOORD0.xy;
    return;
}


#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	mediump float _CFXR_GLOW_POW;
uniform 	mediump float _GlowMin;
uniform 	mediump float _GlowMax;
uniform 	mediump float _MaxValue;
uniform 	mediump float _HdrBoost;
uniform 	mediump float _HdrMultiply;
in mediump  vec4 vs_COLOR0;
in highp  vec2 vs_TEXCOORD0;
layout(location = 0) out mediump vec4 SV_Target0;
mediump float u_xlat16_0;
vec2 u_xlat1;
bool u_xlatb1;
mediump float u_xlat16_2;
float u_xlat3;
void main()
{
    u_xlat16_0 = (-_GlowMin) + _GlowMax;
    u_xlat16_0 = max(u_xlat16_0, 9.99999975e-05);
    u_xlat1.xy = vs_TEXCOORD0.xy * vec2(2.0, 2.0) + vec2(-1.0, -1.0);
    u_xlat1.x = dot(u_xlat1.xy, u_xlat1.xy);
    u_xlat1.x = sqrt(u_xlat1.x);
    u_xlat3 = u_xlat1.x + (-_GlowMin);
    u_xlatb1 = u_xlat1.x>=1.0;
    u_xlat3 = u_xlat3 / u_xlat16_0;
    u_xlat3 = clamp(u_xlat3, 0.0, 1.0);
    u_xlat3 = (-u_xlat3) + 1.0;
    u_xlat16_0 = max(u_xlat3, 9.99999975e-05);
    u_xlat16_0 = log2(u_xlat16_0);
    u_xlat16_2 = exp2(_CFXR_GLOW_POW);
    u_xlat16_0 = u_xlat16_0 * u_xlat16_2;
    u_xlat16_0 = exp2(u_xlat16_0);
    u_xlat3 = min(u_xlat16_0, _MaxValue);
    u_xlat3 = clamp(u_xlat3, 0.0, 1.0);
    u_xlat3 = u_xlat3 * vs_COLOR0.w;
    u_xlat1.x = (u_xlatb1) ? 0.0 : u_xlat3;
    SV_Target0.w = u_xlat1.x;
    u_xlatb1 = _HdrBoost>=0.5;
    u_xlat16_0 = (u_xlatb1) ? _HdrMultiply : 1.0;
    SV_Target0.xyz = vec3(u_xlat16_0) * vs_COLOR0.xyz;
    return;
}
